<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class CommitteeMeeting extends Model{
 protected $fillable=['committee_id','committee_period_id','schedule_item_id','president_member_id','secretary_member_id','meeting_type','meeting_date','start_time','end_time','location','virtual_link','modality','status','called_at','subject','call_notes','quorum_required','quorum_present','has_quorum','confidential_case_id','created_by','updated_by'];protected $casts=['meeting_date'=>'date','called_at'=>'datetime','has_quorum'=>'boolean'];
 public function committee(){return$this->belongsTo(Committee::class);}public function period(){return$this->belongsTo(CommitteePeriod::class,'committee_period_id');}public function scheduleItem(){return$this->belongsTo(CommitteeScheduleItem::class,'schedule_item_id');}public function president(){return$this->belongsTo(CommitteeMember::class,'president_member_id');}public function secretary(){return$this->belongsTo(CommitteeMember::class,'secretary_member_id');}public function attendees(){return$this->hasMany(CommitteeMeetingAttendee::class,'meeting_id');}public function agendaItems(){return$this->hasMany(CommitteeAgendaItem::class,'meeting_id')->orderBy('sort_order');}public function decisions(){return$this->hasMany(CommitteeDecision::class,'meeting_id');}public function commitments(){return$this->hasMany(CommitteeCommitment::class,'meeting_id');}public function minutes(){return$this->hasMany(CommitteeMinute::class,'meeting_id');}public function attendanceEvent(){return$this->morphOne(AttendanceEvent::class,'attendable');}
}
